 assessments=[{'ordinal':i+1,'recorded_ready':r.result['capability_ready'],'question':'Reassess current health/receipt/evaluation and independent review; supplied reports do not prove authentication or business dispatch.'} for i,r in enumerate(IntegrationAssessment.objects.filter(contract__finance_publication_readiness__isnull=True,contract__private_protection_readiness__isnull=True,contract__private_file_readiness__isnull=True,contract__accepted_protection_readiness__isnull=True).exclude(contract__payload__family__in=['supportresponse','supportchannel','ledgerdata']).filter(contract__case=c).order_by('-pk')[:20])]
 observations=list(IntegrationObservation.objects.filter(contract__finance_publication_readiness__isnull=True,contract__private_protection_readiness__isnull=True,contract__private_file_readiness__isnull=True,contract__accepted_protection_readiness__isnull=True).exclude(contract__payload__family__in=['supportresponse','supportchannel','ledgerdata']).filter(contract__case=c).order_by('-pk').values_list('payload',flat=True)[:100]);contracts=list(IntegrationContract.objects.filter(finance_publication_readiness__isnull=True,private_protection_readiness__isnull=True,private_file_readiness__isnull=True,accepted_protection_readiness__isnull=True).exclude(payload__family__in=['supportresponse','supportchannel','ledgerdata']).filter(case=c).order_by('-pk').values_list('payload',flat=True)[:100])
 diagnostics={'history_window':100,'identity_mismatch_count':sum(o.get('identity_match') is False for o in observations),'oracle_mismatch_count':sum(o.get('oracle_match') is False for o in observations),'supplied_report_count':sum(o.get('classification')=='supplied_report' for o in observations),'missing_endpoint_registry_count':sum(v['implementation']=='authenticated_json_v1' and v['target_key'] not in settings.READINESS_ENDPOINTS for v in contracts),'missing_secret_reference_count':sum(v['implementation']=='authenticated_json_v1' and v['credential_ref'] not in settings.READINESS_SECRET_REFS for v in contracts),'policy_status':{k:resolve(k,c).status for k in SCHEMAS}}
